def _normalize_datetime(dt):
    """Handle pytz timezones attached directly via ``tzinfo=...``."""
    if not isinstance(dt, datetime) or dt.tzinfo is None:
        return dt

    if getattr(dt, 'tzname', None) is None or dt.tzname() != 'LMT':
        return dt

    tzinfos = getattr(dt.tzinfo, '_tzinfos', {})
    zone = getattr(dt.tzinfo, 'zone', None)
    if not zone:
        return dt

    for key, tzinfo in tzinfos.items():
        offset, dst, name = key
        if name == zone and not dst:
            return dt.replace(tzinfo=tzinfo)
    return dt

